	if (fd_empty(f))
		return -EBADF;
	sock = sock_from_file(fd_file(f));
	if (unlikely(!sock))
		return -ENOTSOCK;

	return do_sock_setsockopt(sock, compat, level, optname, optval, optlen);
}

